import{_ as e,o as a,c as t,a5 as o}from"./chunks/framework.CXroN2RO.js";const n="/study/images/hardware/dma-and-iommu.svg",M=JSON.parse('{"title":"DMAとIOMMUでデバイスがメモリにアクセスする仕組み","description":"","frontmatter":{"title":"DMAとIOMMUでデバイスがメモリにアクセスする仕組み","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"ドライバーがデバイスへ転送を指示し、SSDやNICがRAMを読み書きする経路を追う。DMAアドレス、IOMMU、キャッシュと順序、割り込みと完了を扱う。","aliases":["DMA","direct memory access","IOMMU","DMA address","IOVA","MMIO","doorbell","scatter/gather","descriptor","割り込み","MSI-X"],"verification":"NVM Expressの仕様、LinuxカーネルのDMA・MMIO資料、Microsoftのドライバー資料に照合（2026-11-07）"}},"headers":[],"relativePath":"hardware/io/dma-and-iommu.md","filePath":"hardware/io/dma-and-iommu.md"}'),s={name:"hardware/io/dma-and-iommu.md"};function i(d,r,l,h,c,m){return a(),t("div",null,[...r[0]||(r[0]=[o('<h1 id="dmaとiommuでデバイスがメモリにアクセスする仕組み" tabindex="-1">DMAとIOMMUでデバイスがメモリにアクセスする仕組み <a class="header-anchor" href="#dmaとiommuでデバイスがメモリにアクセスする仕組み" aria-label="Permalink to &quot;DMAとIOMMUでデバイスがメモリにアクセスする仕組み&quot;">​</a></h1><p>NVMe SSDがファイルのデータを読み出したり、ネットワークカード（NIC）がパケットを受信したりすると、デバイスはシステムメモリのバッファへデータを書き込めます。デバイスがホストメモリを読み書きするこの仕組みを**DMA（Direct Memory Access）**と呼びます。CPUで動くドライバーは、アクセスできるバッファを用意し、デバイスが読むコマンドや記述子を作り、結果を回収します。<a href="https://nvmexpress.org/wp-content/uploads/NVM-Express-1_0e.pdf" target="_blank" rel="noreferrer">NVM Express 1.0e §4.1</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/network-interface-card-support" target="_blank" rel="noreferrer">MicrosoftのNICとDMA</a></p><h2 id="nvmeの読み取りをキューからたどる" tabindex="-1">NVMeの読み取りをキューからたどる <a class="header-anchor" href="#nvmeの読み取りをキューからたどる" aria-label="Permalink to &quot;NVMeの読み取りをキューからたどる&quot;">​</a></h2><p>ここでは、ホストメモリ上にコマンドの提出キュー（SQ）と完了キュー（CQ）がある、PCIe接続のNVMe SSDを例にします。ファイルの読み取りがOSのキャッシュから満たせる場合は、OS内の別の経路でデータが返ります。<a href="https://nvmexpress.org/wp-content/uploads/NVM-Express-1_0e.pdf" target="_blank" rel="noreferrer">NVM Express 1.0e §4.1</a> · <a href="/study/os/file-read-journey.html">ファイル読み取りの経路</a></p><ol><li>ドライバーが、転送先のバッファをデバイスからアクセスできるようにします。読み取り対象や転送先の情報をSQに書き、デバイスのドアベルレジスターへ新しい末尾の位置を書き込みます。CPUは、アドレス空間に割り当てられたデバイスのレジスターを、**MMIO（Memory-Mapped I/O）**として操作します。</li><li>NVMeコントローラーはSQからコマンドを取得し、SSDから読み出したデータを指定されたホストバッファへDMAで書き込みます。書き込みコマンドでは、コントローラーがホストバッファからデータを読み出します。</li><li>コントローラーがCQへ完了エントリーを書き、設定に応じて割り込みなどで知らせます。ドライバーはCQから対象コマンドとステータスを確認し、使用済みのエントリーを回収します。<a href="https://nvmexpress.org/wp-content/uploads/NVM-Express-1_0e.pdf" target="_blank" rel="noreferrer">NVM Expressの提出・完了キューとドアベル §3.1・§4.1</a> · <a href="https://docs.kernel.org/driver-api/device-io.html" target="_blank" rel="noreferrer">LinuxのMMIOアクセス</a></li></ol><figure class="study-figure"><img src="'+n+'" alt="上段ではCPUが提出キューとドアベルで依頼し、デバイスがRAMへDMAし、CPUが完了キューで結果を回収する。下段ではCPU仮想アドレスはCPUのページ表を、デバイスのDMAアドレスはIOMMUを通り、同じRAMの物理ページを指す。" width="760" height="510" loading="lazy"><figcaption>転送を始める通知と結果の回収はCPU側が行います。デバイスがRAMにアクセスするときは、デバイス用のアドレスを使います。<a href="/study/images/hardware/dma-and-iommu.svg" target="_blank" rel="noopener noreferrer">DMAとアドレス変換の図を拡大</a></figcaption></figure><h2 id="cpuのポインターとdmaアドレスを区別する" tabindex="-1">CPUのポインターとDMAアドレスを区別する <a class="header-anchor" href="#cpuのポインターとdmaアドレスを区別する" aria-label="Permalink to &quot;CPUのポインターとDMAアドレスを区別する&quot;">​</a></h2><p>CPUがバッファを参照するときの<strong>仮想アドレス</strong>は、CPUのページ表を通ってRAM上の<strong>物理アドレス</strong>へ対応します。デバイスに渡すのは、OSのDMA APIがその機器に対して用意する<strong>DMAアドレス</strong>です。Linuxの資料ではバスアドレス、Windowsのドライバー資料では論理アドレスとも呼びます。OSはDMAの間に必要なメモリを使える状態にし、対応するDMAアドレスを返します。<a href="https://docs.kernel.org/core-api/dma-api-howto.html" target="_blank" rel="noreferrer">LinuxのDMAアドレス空間の解説</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/map-registers" target="_blank" rel="noreferrer">Microsoftの仮想・物理・論理アドレスの解説</a></p><p><strong>IOMMU（I/O Memory Management Unit）<strong>を使う構成では、デバイスが出したI/O仮想アドレス（IOVA）をIOMMUが変換し、許可された物理ページへアクセスさせます。OSはデバイスの属するドメインにマッピングを設定し、アクセスできるメモリを制限できます。ページが物理的に離れていても連続したIOVAを割り当てられる場合があります。機器や構成によっては、複数の範囲を記した</strong>scatter/gather</strong>の一覧や、機器が届く一時バッファを使って転送します。<a href="https://docs.kernel.org/core-api/dma-api.html" target="_blank" rel="noreferrer">LinuxのDMAマッピングAPI</a> · <a href="https://learn.microsoft.com/en-us/windows/security/information-protection/kernel-dma-protection-for-thunderbolt" target="_blank" rel="noreferrer">MicrosoftのIOMMUによるDMAの分離</a></p><h2 id="キャッシュの整合性と見える順序を揃える" tabindex="-1">キャッシュの整合性と見える順序を揃える <a class="header-anchor" href="#キャッシュの整合性と見える順序を揃える" aria-label="Permalink to &quot;キャッシュの整合性と見える順序を揃える&quot;">​</a></h2><table tabindex="0"><thead><tr><th>観点</th><th>ドライバーが揃えるもの</th></tr></thead><tbody><tr><td>CPUとデバイスからの見え方</td><td>DMAマッピングの種類と転送方向に従い、必要に応じてキャッシュの同期を行う。例えばLinuxでストリーミングマッピングを保持したままCPUとデバイスが交代で使うなら、<code>dma_sync_*_for_cpu</code>、<code>dma_sync_*_for_device</code>で受け渡す。</td></tr><tr><td>書き込みの順序</td><td>バッファのアドレスや長さがデバイスに見える順序で書き、記述子の有効フラグやドアベルを更新する。キャッシュコヒーレントなメモリでも、公開順を作るためにDMA用バリアや規定されたMMIOアクセスを使う。</td></tr><tr><td>バッファの寿命</td><td>転送先と記述子をデバイスが参照している間は、マッピングを維持する。完了を確認した後に、CPUへ所有権を戻して再利用・解放する。</td></tr></tbody></table><p>例えば受信側のNICでは、ドライバーが書き込み先をキューへ補充し、NICが受信データを書いて完了を知らせます。ドライバーが完了を確認してから、ネットワークスタックがそのデータを扱います。送信側ではNICがメモリからパケットを読み出します。<a href="/study/hardware/io/nic-receive-queues.html">NICの受信キューとRSS</a> · <a href="https://docs.kernel.org/core-api/dma-api-howto.html" target="_blank" rel="noreferrer">LinuxのDMAマッピングとキャッシュ同期</a> · <a href="https://docs.kernel.org/core-api/wrappers/memory-barriers.html" target="_blank" rel="noreferrer">LinuxのDMAバリアとドアベルの例</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/network-interface-card-support" target="_blank" rel="noreferrer">MicrosoftのNICの送受信</a></p><h2 id="完了の通知と、完了を確認する処理" tabindex="-1">完了の通知と、完了を確認する処理 <a class="header-anchor" href="#完了の通知と、完了を確認する処理" aria-label="Permalink to &quot;完了の通知と、完了を確認する処理&quot;">​</a></h2><p>PCIeデバイスは、<strong>MSI-X</strong>などのメッセージで割り込みを通知できます。複数のキューに割り込みベクターを分ける構成では、ドライバーは対応するキューを処理します。<strong>ポーリング</strong>では、CPU側が完了エントリーを調べます。短い間隔で調べるほど反応を早められる場合があり、その間CPU時間を使います。LinuxのNICで使うNAPIのように、割り込みをきっかけに受信キューをポーリングし、まとめて処理する方式もあります。<a href="https://docs.kernel.org/PCI/msi-howto.html" target="_blank" rel="noreferrer">LinuxのMSI/MSI-Xドライバー解説</a> · <a href="https://docs.kernel.org/networking/napi.html" target="_blank" rel="noreferrer">LinuxのNAPI</a></p><p>デバイスからの完了通知のあと、ドライバーとOSがI/Oの結果を処理し、呼び出し元へ返します。アプリが待つI/O完了通知はこの上の段階です。ゲームのロード時間を調べるときは、リンクの転送、OSの完了、アセットの展開を分けて観察します。<a href="/study/hardware/io/pcie-links.html">PCI Expressのリンクとレーン</a> · <a href="/study/os/io-completion-ports.html">WindowsのI/O完了ポート</a> · <a href="/study/game/directstorage.html">DirectStorageの読み取りと展開</a></p>',15)])])}const f=e(s,[["render",i]]);export{M as __pageData,f as default};
